for (const item of $input.all()) {
    // Leemos los datos que nos llegan (del nodo Edit Fields)
    const raw = item.json.estacion; 

    // Convertimos el valor a número
    let valorNum = parseFloat(raw.valor);

    // Creamos el objeto limpio 'data_processed' exactamente como lo espera el siguiente nodo
    item.json.data_processed = {
        id: raw.estacion,
        nombre: "Av. Ramón y Cajal", // Asignamos el nombre de la estación 11
        latitud: 40.45147,          // Latitud real de la estación 11
        longitud: -3.67735,         // Longitud real de la estación 11
        fecha_procesamiento: raw.fecha_hora,

        // Clasificamos el valor según la magnitud (8=NO2, 10=PM10, 11=PM2_5)
        no2: raw.magnitud === 8 ? valorNum : null,
        pm10: raw.magnitud === 10 ? valorNum : null,
        pm2_5: raw.magnitud === 11 ? valorNum : null
    };

    // Borramos lo antiguo para no arrastrar basura
    delete item.json.estacion;
}

return $input.all();

const items = $input.all();

for (let item of items) {
    // 1. Accedemos a la fecha que está dentro del objeto data_processed
    let fechaString = item.json.data_processed.fecha_procesamiento;
    let fecha = new Date(fechaString);

    // 2. Extraemos las partes usando UTC para que no te cambie la hora por la zona horaria
    item.json.year = fecha.getUTCFullYear().toString();
    item.json.month = String(fecha.getUTCMonth() + 1).padStart(2, '0');
    item.json.day = String(fecha.getUTCDate()).padStart(2, '0');
    item.json.hour = String(fecha.getUTCHours()).padStart(2, '0');

    // 3. Sacamos la información de la estación a la raíz
    item.json.nombre = item.json.data_processed.nombre;
    item.json.latitud = item.json.data_processed.latitud;
    item.json.longitud = item.json.data_processed.longitud;

    // 4. Sacamos también los datos de contaminación
    item.json.no2 = item.json.data_processed.no2;
    item.json.pm10 = item.json.data_processed.pm10;
    item.json.pm2_5 = item.json.data_processed.pm2_5;

    // 5. Borramos el objeto original anidado para dejar el JSON súper limpio
    delete item.json.data_processed;
}

return items;
